<?php
namespace App\Domain\Capabilities; use App\Models\{Capability,CapabilityCategory}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException; final class CapabilityManager { public function save(array $data,?Capability $item,int $userId):Capability{return DB::transaction(function()use($data,$item,$userId){$item??=new Capability;$data['updated_by']=$userId;if(!$item->exists){$data['created_by']=$userId;$data['status']='draft';$data['display_order']=(int)Capability::max('display_order')+1;}else unset($data['status']);$item->fill($data)->save();$this->normalize();return $item;});} public function publish(Capability $item):void{$this->requireContent($item);$item->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);} public function schedule(Capability $item,string $utc):void{$this->requireContent($item);$item->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);} public function unpublish(Capability $item):void{$item->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);} public function archive(Capability $item):void{if(app(CapabilityDependencyInspector::class)->inspect($item)['blocked'])throw ValidationException::withMessages(['capability'=>'Resolve active references before archiving.']);$item->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);} public function restore(Capability $item):void{$item->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);} public function duplicate(Capability $item,int $userId):Capability{return DB::transaction(function()use($item,$userId){$copy=$item->replicate(['status','published_at','scheduled_for','archived_at','created_by','updated_by']);$copy->title.=' (Copy)';$copy->slug=$this->uniqueSlug($item->slug.'-copy');$copy->status='draft';$copy->published_at=$copy->scheduled_for=$copy->archived_at=null;$copy->created_by=$copy->updated_by=$userId;$copy->display_order=(int)Capability::max('display_order')+1;$copy->save();foreach(['highlights','benefits','facts'] as $relation)$item->{$relation}()->each(fn($child)=>$copy->{$relation}()->create($child->only($child->getFillable())));return $copy;});} public function move(Capability $item,string $direction):void{DB::transaction(function()use($item,$direction){$peer=Capability::where('display_order',$direction==='up'?'<':'>',$item->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$item->display_order;$item->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}$this->normalize();});} public function uniqueSlug(string $base):string{$base=Str::slug(Str::lower($base))?:'capability';$slug=$base;for($i=2;Capability::where('slug',$slug)->exists();$i++)$slug=Str::limit($base,150,'')."-$i";return $slug;} private function normalize():void{Capability::orderBy('display_order')->orderBy('id')->get()->each(fn($item,$i)=>$item->display_order===$i+1?null:$item->updateQuietly(['display_order'=>$i+1]));} private function requireContent(Capability $item):void{if(!trim($item->title)||!trim($item->short_description))throw ValidationException::withMessages(['capability'=>'A title and short description are required before publication.']);} public function saveCategory(array $data,?CapabilityCategory $category=null):CapabilityCategory{return DB::transaction(function()use($data,$category){$category??=new CapabilityCategory;if(!$category->exists)$data['display_order']=(int)CapabilityCategory::max('display_order')+1;$category->fill($data)->save();$this->normalizeCategories();return $category;});} public function moveCategory(CapabilityCategory $category,string $direction):void{DB::transaction(function()use($category,$direction){$peer=CapabilityCategory::where('display_order',$direction==='up'?'<':'>',$category->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$category->display_order;$category->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}$this->normalizeCategories();});} private function normalizeCategories():void{CapabilityCategory::orderBy('display_order')->orderBy('id')->get()->each(fn($item,$i)=>$item->display_order===$i+1?null:$item->updateQuietly(['display_order'=>$i+1]));} }
